  function defectHead() { return ['cNc', 'cDate', 'cLine', 'cCat', 'cRca', 'cSub', 'cCode', 'cFin', 'cCab', 'cText'].map(function (k) { return '<th scope="col">' + esc(S(k)) + '</th>'; }).join(''); }
  function defectRow(r) {
    return '<tr><td class="nc">' + esc(r[0]) + (r[1] > 1 ? ' · ' + r[1] : '') + '</td><td class="num">' + esc(shortDay(r[2])) + '</td><td>' + esc(r[4]) + '</td><td>' + esc(L(dCat(r))) + '</td><td>' + esc(L(dRca(r))) + '</td><td>' + esc(dSub(r)) + '</td><td class="nc" title="' + esc(codeDesc(dCode(r))) + '">' + esc(dCode(r)) + '</td><td class="nc">' + esc(dFin(r)) + '</td><td>' + (dCable(r) ? '<span class="tag">' + esc(S('yes')) + '</span>' : '') + '</td><td class="txt">' + esc(tidy(r[18])) + '</td></tr>';
  }
  function defectText(r) { return r[0] + ' ' + r[18] + ' ' + dFin(r) + ' ' + dCode(r) + ' ' + codeDesc(dCode(r)) + ' ' + dSub(r) + ' ' + dRca(r) + ' ' + L(dRca(r)) + ' ' + dCat(r) + ' ' + L(dCat(r)); }
  function byDate(a, b2) { return a[2] < b2[2] ? 1 : a[2] > b2[2] ? -1 : (a[0] < b2[0] ? 1 : a[0] > b2[0] ? -1 : a[1] - b2[1]); }
  function topOf(m) { return Object.keys(m).sort(function (x, y) { return m[y] - m[x]; })[0]; }

  // ---------------------------------------------------------------- 1. Overview: headline figures, each chart counts NCs of the selection
  // NC row extras: [32] closure date, [33] NC type, [34] liability, [35] SAP defect code, [36] SAP cause group, [37] SAP cause, [38] status
  var PROG_COL = { A350: 'var(--l1)', A330: 'var(--l2)', A320: 'var(--l3)', A400M: 'var(--l4)' };   // no blue or green: those are the categories' (20 Oct)
  function lineCol(l) { return PROG_COL[l] || 'var(--dim)'; }   // one colour per line on every chart
  // a product takes the colour of its line (the line of most of its NCs), as on Localisation; 'Other' stays grey (29 Oct)
  var PROD_LINE = (function () { var c = {}, r = {}; D.ncs.forEach(function (n) { var p = n[26] || 'Other', o = c[p] || (c[p] = {}); o[n[3]] = (o[n[3]] || 0) + 1; });
    Object.keys(c).forEach(function (p) { var b = '', bv = 0; Object.keys(c[p]).forEach(function (l) { if (c[p][l] > bv) { bv = c[p][l]; b = l; } }); r[p] = b; }); return r; })();
  function prodCol(p) { return p === 'Other' ? 'var(--dim)' : lineCol(PROD_LINE[p]); }
  var TYPE_ALIAS = { 'NC Interne': 'INTERNE', 'NC Retour client': 'RETOUR CLIENT', 'CLIENT': 'RETOUR CLIENT' };
  function ncType(n) { var t = String(n[33] || '').trim(); return TYPE_ALIAS[t] || t; }
  function typeName(t) { return STR[G.lang]['ty_' + t] || t; }
  function stName(s) { return STR[G.lang]['st_' + s] || s || '—'; }
  function median(a) { if (!a.length) return null; a = a.slice().sort(function (x, y) { return x - y; }); var i = Math.floor(a.length / 2); return a.length % 2 ? a[i] : (a[i - 1] + a[i]) / 2; }
  // donut with a legend; slices and legend rows filter like bars
  function pie(vals, m, rs, b) {
    var d = this, tot = 0; vals.forEach(function (v) { tot += m[v] || 0; });
    if (!tot) return '<p class="empty">—</p>';
    var R = 84, r0 = 52, a = -Math.PI / 2, gl = d.pickLine, act = gl ? !!GF.line : d.k in b.f, shapes = '', leg = '';   // pickLine: a click is the global line filter
    function pt(r, t) { return (90 + r * Math.cos(t)).toFixed(1) + ',' + (90 + r * Math.sin(t)).toFixed(1); }
    vals.forEach(function (v, i) {
      var n = m[v] || 0, on = gl ? GF.line === v : b.f[d.k] === v, col = d.color(v, i), fade = act && !on ? ' opacity=".3"' : '', lab = d.show(v), tip = lab + ' : ' + num(n) + ' (' + pct0(n / tot * 100) + ')';
      var hit = gl ? (v === 'Autre' ? '' : pk('line', v)) : ' data-dim="' + d.k + '" data-v="' + esc(v) + '"', attrs = hit + fade + '><title>' + esc(tip) + '</title>';
      if (n === tot) shapes += '<circle cx="90" cy="90" r="' + (R + r0) / 2 + '" fill="none" stroke="' + col + '" stroke-width="' + (R - r0) + '"' + attrs + '</circle>';
      else if (n) { var a1 = a + n / tot * 2 * Math.PI, big = a1 - a > Math.PI ? 1 : 0;
        shapes += '<path d="M' + pt(R, a) + 'A' + R + ',' + R + ' 0 ' + big + ' 1 ' + pt(R, a1) + 'L' + pt(r0, a1) + 'A' + r0 + ',' + r0 + ' 0 ' + big + ' 0 ' + pt(r0, a) + 'Z" fill="' + col + '" stroke="var(--surface)" stroke-width="2"' + attrs + '</path>';
        a = a1; }
      leg += '<button type="button" class="pleg"' + hit + ' aria-pressed="' + on + '"><i style="background:' + col + '"></i><span class="name">' + esc(lab) + '</span><span class="val">' + num(n) + '</span><span class="cum">' + pct0(n / tot * 100) + '</span></button>';
    });
    return '<div class="piewrap"><svg class="viz" viewBox="0 0 180 180" width="180" height="180" role="img" aria-label="' + esc(S(d.t)) + '">' + shapes +
      '<text x="90" y="92" text-anchor="middle" class="ink b" style="font-size:20px">' + num(tot) + '</text><text x="90" y="110" text-anchor="middle" class="mu">' + esc(S('nK1')) + '</text></svg><div class="pielegend">' + leg + '</div></div>';
  }
  // two lines per month: NCs created, NCs closed; a month click keeps the NCs created that month
  // cost of non-quality split by NC type, one 100 % bar; NC Interne and Casse interne count as Interne
