    function X(i) { return ml + (months.length > 1 ? i * sx : pw / 2); } function Y(v) { return mt + ph - v / top * ph; }
    var g = '<line x1="' + ml + '" x2="' + (ml + pw) + '" y1="' + Y(0) + '" y2="' + Y(0) + '" stroke="var(--grid)"/>';
