  // ---------------------------------------------------------------- 3. Weekly Pareto (follow-up page): running window of 1, 5 or 10 weeks
  var defaultWeek = (function () { for (var i = WEEKS.length - 1; i >= 0; i--) { if (!isPartial(WEEKS[i])) return WEEKS[i]; } return WEEKS[WEEKS.length - 1]; })();
  var W = { week: defaultWeek, win: 5, lvl: 'cat', prob: null };
