  function toSet(a) { var s = {}; a.forEach(function (x) { s[x] = 1; }); return s; }
  function lvlOf(lvl, r) { return lvl === 'cat' ? dCat(r) : lvl === 'rca' ? dRca(r) : dCode(r); }
  function lvlGet(r) { return lvlOf(W.lvl, r); }
