    // the plan month by month, one colour per line; the months still to come lighter
    var mc = document.getElementById('ppMonthC'), W = Math.max(300, mc.clientWidth || 520), H = 230, ml = 34, mb = 22, mt = 14, n = PD.months.length, bw = (W - ml) / n, LN = lineOrder(Object.keys(by));
