    document.getElementById('rth').innerHTML = [['rRca'], ['rCat'], ['rDef', 'r'], ['rShare', 'r'], ['rNc', 'r'], ['rCostS', 'r'], ['rCli', 'r']].map(function (p) { return '<th scope="col"' + (p[1] ? ' class="r"' : '') + '>' + esc(S(p[0])) + '</th>'; }).join('');
