    g += tx(ml + pw / 2, H - 6, S('axNcShare'), 'mu', 'middle') + '<line class="iso" x1="' + X(0) + '" y1="' + Y(0) + '" x2="' + X(1) + '" y2="' + Y(1) + '"/>';
    function path(c) { var step = Math.max(1, Math.floor(N / 400)), pts = []; for (var i = 0; i <= N; i += step) pts.push(r1(X(i / N)) + ',' + r1(Y(c[i]))); pts.push(r1(X(1)) + ',' + r1(Y(1))); return 'M' + pts.join('L'); }
