    months.forEach(function (m) { Object.keys(cnt[m]).sort(function (a, b) { return cnt[m][b] - cnt[m][a] || (a < b ? -1 : 1); }).forEach(function (a, i) { (rank[m] || (rank[m] = {}))[a] = i + 1; }); });
