  function hideTip() { TIP.hidden = true; }
  function showTip(e, parts) {
    TIP.textContent = '';
    var h = document.createElement('span'); h.className = 'th'; h.textContent = parts[0]; TIP.appendChild(h);
    parts.slice(1).forEach(function (p, i) { var s = document.createElement(i ? 'span' : 'b'); s.textContent = p; TIP.appendChild(s); });
    TIP.hidden = false;
    var w = TIP.offsetWidth, hh = TIP.offsetHeight, x = e.clientX + 14, y = e.clientY + 16;
    if (x + w > innerWidth - 8) x = e.clientX - w - 14; if (y + hh > innerHeight - 8) y = e.clientY - hh - 12;
    TIP.style.left = Math.max(8, x) + 'px'; TIP.style.top = Math.max(8, y) + 'px';
  }
  var flowKey = null;
  function flowFocus(svgEl, key, link) {
    if (!svgEl) return;
    var on = !!(key || link); svgEl.classList.toggle('focus', on);
    svgEl.querySelectorAll('.lnk').forEach(function (p) { p.classList.toggle('hl', !!(link ? p === link : key && (p.getAttribute('data-a') === key || p.getAttribute('data-b') === key))); });
  }
