      cross.setAttribute('x1', xx); cross.setAttribute('x2', xx);
      showTip(e, [S('lorTipH', { p: pct0(i / A.lor.N * 100), n: num(i) }), S('lorD') + ' : ' + pct(A.lor.cd[i] * 100), S('lorC') + ' : ' + pct(A.lor.cc[i] * 100)]);
