      g += '<line x1="' + ml + '" x2="' + (W0 - mr) + '" y1="' + r1(Y(0)) + '" y2="' + r1(Y(0)) + '" stroke="var(--grid)"/>';
      g += '<path d="' + pts.map(function (p) { return 'M' + r1(X(p.i) - st / 2) + ',' + r1(Y(p.ucl)) + 'H' + r1(X(p.i) + st / 2); }).join('') + '" stroke="var(--up)" stroke-width="1.5" stroke-dasharray="3 2" fill="none"/>';
      g += '<line x1="' + ml + '" x2="' + (W0 - mr) + '" y1="' + r1(Y(ub)) + '" y2="' + r1(Y(ub)) + '" stroke="var(--ink-2)"/>' + tx(W0 - mr + 8, Y(ub) + 4, gx('mean') + ' ' + f1(ub), 'mu');
      g += '<path d="' + pts.map(function (p, j) { return (j ? 'L' : 'M') + r1(X(p.i)) + ',' + r1(Y(p.u)); }).join('') + '" fill="none" stroke="var(--s1)" stroke-width="1.5"/>';
