          tip(weekLong(p.w) + ' · ' + l, [gx('uTip', { u: f1(p.u), c: num(p.c), n: num(p.n) }), gx('uclTip', { v: f1(p.ucl) }) + (out ? ' · ' + gx('outLim') : '')]) + '/>';
