        if (r.w > 78 && r.h > 36) { var mc = Math.floor((r.w - 14) / 6.6); if (nm.length > mc) nm = nm.slice(0, mc - 1) + '…'; g += tx(r.x + 8, r.y + 18, nm, 'ink b') + tx(r.x + 8, r.y + 33, eurK(r.it.v), 'ink'); }
