    var W0 = gWd(k), keys = MAIN_CATS.slice(), n = keys.length, M = keys.map(function () { return keys.map(function () { return 0; }); }), per = {}, single = 0;
    GD.forEach(function (d) { (per[d[0]] || (per[d[0]] = {}))[catKey(d[1])] = 1; });
    Object.keys(per).forEach(function (i) { var cs = Object.keys(per[i]); if (cs.length < 2) { single++; return; } cs.forEach(function (a) { cs.forEach(function (b) { if (a !== b) M[keys.indexOf(a)][keys.indexOf(b)]++; }); }); });
