      g += '<line x1="' + lab + '" x2="' + r1(X(r.r)) + '" y1="' + y + '" y2="' + y + '" stroke="' + col + '" stroke-width="2"/>';
      g += '<circle cx="' + r1(X(r.r)) + '" cy="' + y + '" r="5.5" fill="' + col + '" stroke="var(--surface)" stroke-width="2"/>';
      g += '<circle cx="' + r1(X(r.r)) + '" cy="' + y + '" r="13" fill="transparent"' + tip(r.p + ' · ' + r.l, [f2(r.r) + ' ' + (G.lang === 'fr' ? 'pour 10 000' : 'per 10,000'), gx('rateTip', { e: num(r.e), i: num(r.ins), u: num(r.u) })]) + '/>';
