  var RV = { st: {}, view: {}, show: 'all', db: null, live: false, saving: 0, err: '', built: false };
  var RV_ANA = { lead: function () { vLead(); }, bump: function () { vBump(aRows()); }, mek: function () { vMek(aRows(true)); }, cal: function () { vCal(aRows()); }, lor: function () { vLor(aRows()); }, clock: function () { vClock(); },
    flow: function () { vFlow(aRows()); }, bub: function () { vBub(aRows()); }, msn: function () { vMsn(); }, prod: function () { vProd(); }, station: function () { vStation(aRows()); } };
  function rvItems() { var a = []; REV.forEach(function (sec) { sec.items.forEach(function (it) { a.push(it); }); }); return a; }
  function rvIsAna(c) { return c.indexOf('A:') === 0; }
  function rvCard(c) { return document.getElementById(rvIsAna(c) ? 'v-' + c.slice(2) : 'g-' + c); }
  function rvTitle(it) { var t = it[G.lang][0]; if (t) return t; var c = it.c[0]; return rvIsAna(c) ? S('t_' + c.slice(2)) : GSTR[c][G.lang][1]; }
  function rvShown(it) { return it.m === 'all' ? it.c : [RV.view[it.id] || (RV.st[it.id] && RV.st[it.id].pick) || it.c[0]]; }
  function rvDraw(c) {
    if (rvIsAna(c)) { EMPTY = '<p class="empty">—</p>'; RV_ANA[c.slice(2)](); return; }
    var t = GSTR[c][G.lang], gal = +c <= 50, sp = (gal ? GSPEC : PSPEC).filter(function (x) { return x[0] === c; })[0];
    document.getElementById('g-' + c + '-k').textContent = t[0];
    document.getElementById('g-' + c + '-h').textContent = t[1];
    document.getElementById('g-' + c + '-s').textContent = t[2];
    var f = document.getElementById('g-' + c + '-f');
    if (gal) { f.className = 'feas ' + sp[1]; f.innerHTML = '<i aria-hidden="true">' + { ok: '✓', part: '◐', need: '○' }[sp[1]] + '</i>' + esc(gx('f_' + sp[1]) + ' · ' + t[3]); sp[2](c); }
    else { f.className = 'feas ok'; f.innerHTML = '<i aria-hidden="true">✓</i>' + esc(gx('pReal') + ' · ' + t[3]); sp[1](c); }
  }
  function rvBuild() {
    var n = 0, body = document.getElementById('rvBody');
    body.innerHTML = REV.map(function (sec) {
      return '<section class="rv-sec" id="rvs-' + sec.s + '"><h3 id="rvs-' + sec.s + '-h"></h3>' + sec.items.map(function (it) {
        n++;
        return '<article class="rv-item" id="rv-' + it.id + '"><div class="rv-left"><span class="rv-num">' + n + '</span><h4 id="rv-' + it.id + '-h"></h4><p class="sub" id="rv-' + it.id + '-n"></p>' +
          '<p class="rv-src" id="rv-' + it.id + '-src"></p><div class="rv-tags" id="rv-' + it.id + '-tags"></div>' +
          '<div class="rv-ctl"><div class="rv-ctlb" style="display:contents" id="rv-' + it.id + '-ctl"></div><label for="rv-' + it.id + '-note" data-t="rvNote"></label>' +
          '<input type="text" id="rv-' + it.id + '-note" data-rvnote="' + it.id + '" maxlength="300" autocomplete="off"></div></div>' +
          '<div class="rv-right" id="rv-' + it.id + '-r">' + (it.m === 'sw' || it.m === 'pick' ? '<div class="seg" role="group" id="rv-' + it.id + '-sw"></div>' : '') + '</div></article>';
      }).join('') + '</section>';
    }).join('');
    rvItems().forEach(function (it) { var r = document.getElementById('rv-' + it.id + '-r'); it.c.forEach(function (c) { var el = rvCard(c); if (el) r.appendChild(el); }); });
    RV.built = true;
  }
  function rvCtlHtml(it) {
    var st = RV.st[it.id] || {}, b = function (f, v, lab) { return '<button type="button" data-rv="' + it.id + '|' + f + '|' + v + '" aria-pressed="' + (st[f] === v) + '">' + esc(lab) + '</button>'; };
    var h = '<span>' + esc(S('rvKeep')) + '</span><div class="seg" role="group">' + b('keep', 'oui', S('rvYes')) + b('keep', 'non', S('rvNo')) + '</div>';
    if (it.m === 'pick') h += '<span>' + esc(S('rvPick')) + '</span><div class="seg" role="group">' + it.c.map(function (c) { return b('pick', c, it.o[c][G.lang === 'fr' ? 0 : 1]); }).join('') + '</div>';
    h += '<span>' + esc(S('rvPrio')) + '</span><div class="seg" role="group">' + ['a', 'b', 'c', 'd', 'e'].map(function (v) { return b('prio', v, v); }).join('') + '</div><small>' + esc(S('rvPrioHint')) + '</small>';
    h += '<span>' + esc(S('rvWhen')) + '</span><div class="seg" role="group">' + b('when', 'now', S('rvNow')) + b('when', 'later', S('rvLater')) + '</div>';
    return h;
  }
  function rvState() {   // choices, tags, counts and save status; no chart drawing
    if (PAGE !== 'review' || !RV.built) return;
    var all = rvItems(), k = 0, r = 0;
    all.forEach(function (it) {
      var st = RV.st[it.id] || {}, el = document.getElementById('rv-' + it.id);
      if (st.keep === 'oui') k++; else if (st.keep === 'non') r++;
      el.hidden = RV.show === 'open' ? !!st.keep : RV.show === 'kept' ? st.keep !== 'oui' : RV.show === 'dropped' ? st.keep !== 'non' : false;
      document.getElementById('rv-' + it.id + '-ctl').innerHTML = rvCtlHtml(it);
      var note = document.getElementById('rv-' + it.id + '-note');
      if (document.activeElement !== note) note.value = st.note || '';
      note.placeholder = S('rvNotePh'); note.previousElementSibling.textContent = S('rvNote');
    });
    document.getElementById('rvSum').textContent = S('rvSum', { n: all.length, k: k, r: r, u: all.length - k - r });
    document.getElementById('rvShow').innerHTML = segHtml([['all', S('rvAll')], ['open', S('rvOpen')], ['kept', S('rvKept')], ['dropped', S('rvDropped')]], RV.show, 'data-rvshow');
    var sv = document.getElementById('rvSave'), ro = RV.err === 'ro';
    sv.textContent = RV.saving ? S('rvSaving') : RV.err ? S(ro ? 'rvReadOnly' : 'rvSaveErr') : RV.live ? S('rvSaveDb') : S('rvSaveLocal');
    sv.className = 'rv-save' + (RV.err ? ' warn' : RV.live && !RV.saving ? ' ok' : '');
  }
  function rvDrawItem(it) {
    var shown = rvShown(it), sw = document.getElementById('rv-' + it.id + '-sw');
    if (sw) sw.innerHTML = '<span class="rv-alt" style="padding:5px 10px">' + esc(S('rvView')) + '</span>' + it.c.map(function (c) { return '<button type="button" data-rvsw="' + it.id + '|' + c + '" aria-pressed="' + (shown.indexOf(c) >= 0) + '">' + esc(it.o[c][G.lang === 'fr' ? 0 : 1]) + '</button>'; }).join('');
    it.c.forEach(function (c) { var el = rvCard(c); if (el) el.hidden = shown.indexOf(c) < 0; });
    shown.forEach(rvDraw);
  }
  function renderRev() {
    if (PAGE !== 'review' || G.tab !== 'rev') return;
    if (!RV.built) rvBuild();
    if (pSrc()) { PD = pData(); PA = pAgg(PD); }
    REV.forEach(function (sec) { document.getElementById('rvs-' + sec.s + '-h').textContent = sec[G.lang]; });
    rvItems().forEach(function (it) {
      var t = it[G.lang], fict = it.c.filter(function (c) { return !rvIsAna(c) && +c <= 50; }).length, tags = '';
      document.getElementById('rv-' + it.id + '-h').textContent = rvTitle(it);
      document.getElementById('rv-' + it.id + '-n').textContent = t[1];
      document.getElementById('rv-' + it.id + '-src').textContent = S('rvCharts', { l: it.c.map(function (c) { return rvIsAna(c) ? S('rvCurrent') + ' : ' + S('t_' + c.slice(2)) : c; }).join(' · ') });
      tags += '<span class="rv-tag ' + (it.p === 'drop' ? 'drop' : it.p === 'later' || it.p === 'opt' ? 'later' : 'keep') + '">' + esc(S({ keep: 'rvPropKeep', drop: 'rvPropDrop', later: 'rvPropLater', opt: 'rvPropOpt', pick: 'rvPropPick' }[it.p])) + '</span>';
      tags += '<span class="rv-tag ' + (fict ? 'rv-fict' : 'rv-real') + '">' + esc(S(fict === it.c.length ? 'rvFict' : fict ? 'rvMixed' : 'rvReal')) + '</span>';
      document.getElementById('rv-' + it.id + '-tags').innerHTML = tags;
      rvDrawItem(it);
    });
    rvState();
  }
  // saving: this browser always; the page's store when the viewer runs it, one write at a time per document
  var RVQ = {}, RVT = {};
  function rvLocal() { try { if (!EMBED) localStorage.setItem('fto2-rev-choix', JSON.stringify(RV.st)); } catch (e) {} }
  function rvSave(id) {
    rvLocal();
    if (!RV.db) { rvState(); return; }
    var body = Object.assign({}, RV.st[id] || {}, { at: new Date().toISOString() });
    RV.saving++; rvState();
    RVQ[id] = (RVQ[id] || Promise.resolve()).then(function () { return RV.db.collection('choix').doc(id).set(body); })
      .then(function () { if (RV.err !== 'ro') RV.err = ''; }, function (e) { RV.err = e && e.code === 'invalid_argument' ? 'ro' : 'err'; })
      .then(function () { RV.saving--; rvState(); });
  }
  if (PAGE === 'review') {
    try { RV.st = JSON.parse(localStorage.getItem('fto2-rev-choix') || '{}') || {}; } catch (e) {}
    var RP = document.getElementById('p-rev');
    RP.addEventListener('click', function (e) {
      var b = e.target.closest('[data-rv]');
      if (b) {
        var p = b.getAttribute('data-rv').split('|'), it = rvItems().filter(function (x) { return x.id === p[0]; })[0], st = RV.st[p[0]] = Object.assign({}, RV.st[p[0]] || {});
        st[p[1]] = st[p[1]] === p[2] ? '' : p[2];
        if (p[1] === 'pick' && st.pick) { RV.view[p[0]] = st.pick; rvDrawItem(it); }
        rvSave(p[0]); return;
      }
      var w = e.target.closest('[data-rvsw]');
      if (w) { var q = w.getAttribute('data-rvsw').split('|'); RV.view[q[0]] = q[1]; rvDrawItem(rvItems().filter(function (x) { return x.id === q[0]; })[0]); return; }
      var f = e.target.closest('[data-rvshow]'); if (f) { RV.show = f.getAttribute('data-rvshow'); rvState(); return; }
      if (e.target.closest('#rvCopy')) rvCopy();
    });
    RP.addEventListener('input', function (e) {
      var id = e.target.getAttribute && e.target.getAttribute('data-rvnote'); if (!id) return;
      RV.st[id] = Object.assign({}, RV.st[id] || {}, { note: e.target.value });
      clearTimeout(RVT[id]); RVT[id] = setTimeout(function () { rvSave(id); }, 700);
    });
    RP.addEventListener('pointermove', function (e) { var t = e.target.closest && e.target.closest('[data-tip]'); if (t) showTip(e, t.getAttribute('data-tip').split('|')); else hideTip(); });
    RP.addEventListener('pointerleave', hideTip);
    if (!EMBED && window.claude && typeof window.claude.use === 'function') {
      window.claude.use('db').then(function (db) {
        if (!db) return;
        RV.db = db;
        db.collection('choix').onSnapshot(function (snap) {
          snap.docs.forEach(function (d) {
            if (!d.exists) return;
            var v = Object.assign({}, d.data()), ne = document.getElementById('rv-' + d.id + '-note'); delete v.at;
            if (ne && document.activeElement === ne) v.note = ne.value;   // keep what is being typed
            RV.st[d.id] = v;
          });
          RV.live = true; rvLocal(); rvState();
        }, function () { RV.db = null; RV.live = false; rvState(); });
      }, function () {});
    }
  }
  function rvCopy() {
    var L2 = G.lang === 'fr' ? 0 : 1, n = 0, out = [S('titleRev') + ' · ' + new Date().toLocaleDateString(loc())];
    REV.forEach(function (sec) {
      out.push('', '[' + sec[G.lang] + ']');
      sec.items.forEach(function (it) {
        n++; var st = RV.st[it.id] || {}, parts = [];
        parts.push(S('rvKeep') + ' ' + (st.keep === 'oui' ? S('rvYes') : st.keep === 'non' ? S('rvNo') : S('rvUndecided')));
        if (st.pick) parts.push(S('rvPick') + ' ' + it.o[st.pick][L2]);
        if (st.prio) parts.push(S('rvPrio') + ' ' + st.prio);
        if (st.when) parts.push(st.when === 'now' ? S('rvNow') : S('rvLater'));
        if (st.note) parts.push('« ' + st.note + ' »');
        out.push(n + '. ' + rvTitle(it) + ' (' + it.c.map(function (c) { return rvIsAna(c) ? S('rvCurrent') : c; }).join(', ') + ') : ' + parts.join(' · '));
      });
    });
    var text = out.join('\n'), box = document.getElementById('rvCopyBox');
    var shown = function () { box.hidden = false; box.value = text; box.focus(); box.select(); document.getElementById('rvSave').textContent = S('rvCopyHint'); };
    if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(text).then(function () { box.hidden = true; document.getElementById('rvSave').textContent = S('rvCopied'); }, shown);
    else shown();
  }

