        var k = w.getAttribute('data-mkw'); if (seen[k]) return; seen[k] = 1;
        var host = w.closest('.mk-cell') || w.closest('.mk-inline') || w.closest('.card') || w.parentNode, h = host.querySelector('h3') || host.querySelector('b');
